import pytestfrom src.masks import get_mask_account, get_mask_card_numberdef test_get_mask_card_number_valid() -> None:    """Тест корректного номера карты"""    card_number = "1234 5678 9012 3456"    expected = "1234 56** **** 3456"    assert get_mask_card_number(card_number) == expecteddef test_get_mask_card_number_short() -> None:    """Тест слишком короткого номера карты"""    card_number = "1234 5678 9012"    with pytest.raises(ValueError, match="Номер карты должен состоять из 16 цифр"):        get_mask_card_number(card_number)def test_get_mask_card_number_long() -> None:    """Тест слишком длинного номера карты"""    card_number = "1234 5678 9012 3456 7890"    with pytest.raises(ValueError, match="Номер карты должен состоять из 16 цифр"):        get_mask_card_number(card_number)def test_get_mask_card_number_invalid_chars() -> None:    """Тест номера с недопустимыми символами"""    card_number = "1234 5678 9012 34a6"    with pytest.raises(ValueError, match="Номер карты должен содержать только цифры"):        get_mask_card_number(card_number)def test_get_mask_card_number_no_spaces() -> None:    """Тест номера без пробелов"""    card_number = "1234567890123456"    expected = "1234 56** **** 3456"    assert get_mask_card_number(card_number) == expecteddef test_get_mask_card_number_with_extra_spaces() -> None:    """Тест номера с дополнительными пробелами"""    card_number = "1234  5678  9012  3456"    expected = "1234 56** **** 3456"    assert get_mask_card_number(card_number) == expecteddef test_get_mask_card_number_with_leading_trailing_spaces() -> None:    """Тест номера с пробелами в начале и конце"""    card_number = " 1234 5678 9012 3456 "    expected = "1234 56** **** 3456"    assert get_mask_card_number(card_number) == expecteddef test_get_mask_account() -> None:    """Тестирование маскировки номера счета"""    # Проверка стандартного номера счета    assert get_mask_account("73654108430135874305") == "**4305"    # Проверка короткого номера    assert get_mask_account("1234") == "**1234"    # Проверка пустой строки (должна вернуть первые 2 звездочки)    assert get_mask_account("") == "**"    # Проверка слишком короткого номера (менее 4 символов)    assert get_mask_account("12") == "**12"@pytest.mark.parametrize("card_number, expected", [    ("4111111111111111", "4111 11** **** 1111"),    ("5500000000000004", "5500 00** **** 0004"),])def test_various_card_numbers(card_number: str, expected: str) -> None:    assert get_mask_card_number(card_number) == expected@pytest.mark.parametrize("account_number, expected", [    ("00000000000000001234", "**1234"),    ("99999999999999999999", "**9999"),])def test_various_account_numbers(account_number: str, expected: str) -> None:    assert get_mask_account(account_number) == expecteddef test_main_output() -> None:    """Проверка вывода функций маскировки"""    assert get_mask_card_number("7000792289606361") == "7000 79** **** 6361"    assert get_mask_account("73654108430135874305") == "**4305"